package basics;

public class ArithmeticOperations {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		 
		int n1=400, n2=200;
		
	System.out.println("The Addition of " + n1 +"and" + n2 + ":" + (n1+n2));
	System.out.println("The subtraction of " + n1 +"and" + n2 + ":" + (n1-n2));
	System.out.println("The multiplication of " + n1 +"and" + n2 + ":" + (n1*n2));
	System.out.println("The division of " + n1 +"and" + n2 + ":" + (n1/n2));
	System.out.println("The Modulus division of " + n1 +"and" + n2 + ":" + (n1%n2));

	}

}
